//! The runtime of learned inflection grammars.
//!
//! A language crate generated by `flexion-train` is its grammar, written as
//! Rust: for each part of speech, its [paradigms](Paradigm) (how a group of
//! words inflects, one pattern per cell), the [choices](Choice) that decide
//! which paradigm a word follows and how it is stressed (ordered rules on the
//! word's ending, each with its evidence, and the words no rule gets right),
//! its stress patterns and its sound laws. This crate holds those types and
//! answers from them: [`Grammar::candidates`] gives each possible form with a
//! probability, how settled it is, and why.
//!
//! The trainer builds the same values (owned instead of borrowed) and checks
//! them before it prints them, so a crate answers exactly as the grammar
//! it was printed from.

#![forbid(unsafe_code)]

mod choice;
mod grammar;
mod orthography;
mod paradigm;
pub mod pattern;
mod stress;

pub use choice::{Choice, Reading, Rule, Status, by_ending, tolerance};
pub use grammar::{Compound, Grammar, Known, sharpen};
pub use orthography::{Casing, Orthography, Stress, Written, recase};
pub use paradigm::{Form, Paradigm, Referral};
pub use sound_law;
pub use stress::{Accent, AccentPattern, Place, StressClass, place as stress_place};

use std::fmt;

/// A value a [`Choice`] gives: a paradigm, a stress pattern, a vowel.
/// Generated crates use their own enums (`Declension::Книга`); the trainer
/// uses plain numbers.
pub trait Label: Copy + Eq + fmt::Debug + 'static {
    /// The value's place in its grammar's table.
    fn index(self) -> usize;
    /// The value at a place in the table.
    fn from_index(index: usize) -> Option<Self>;
}

impl Label for u8 {
    fn index(self) -> usize {
        usize::from(self)
    }
    fn from_index(index: usize) -> Option<Self> {
        u8::try_from(index).ok()
    }
}

impl Label for u16 {
    fn index(self) -> usize {
        usize::from(self)
    }
    fn from_index(index: usize) -> Option<Self> {
        u16::try_from(index).ok()
    }
}

/// One possible form, how likely it is, and why.
#[derive(Debug, Clone, PartialEq)]
pub struct Candidate<'g> {
    /// The form, written as the language writes it (stress marks included).
    pub form: String,
    /// Other forms the same reading allows in the cell (`ня́нею` beside
    /// `ня́ней`).
    pub also: Vec<String>,
    /// How likely this form is, from 0 to 1.
    pub probability: f32,
    /// Whether the dictionary lists the word, a productive rule gives it, or
    /// the words like it disagree.
    pub status: Status,
    /// The paradigm, named after its commonest word.
    pub paradigm: &'g str,
    /// The rule that chose the paradigm, when no listing did.
    pub evidence: Option<Evidence<'g>>,
}

/// The evidence behind a rule: of the dictionary's `total` words ending in
/// `ending`, `count` inflect this way.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Evidence<'g> {
    pub ending: &'g str,
    pub count: u32,
    pub total: u32,
}

impl fmt::Display for Candidate<'_> {
    /// `книги (97%, regular): like книга; 1203 of 1210 words in -га`
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let status = match self.status {
            Status::Listed => "listed",
            Status::Regular => "regular",
            Status::Unsettled => "unsettled",
        };
        write!(
            f,
            "{} ({:.0}%, {status}): like {}",
            self.form,
            self.probability * 100.0,
            self.paradigm
        )?;
        if let Some(e) = self.evidence {
            if e.ending.is_empty() {
                write!(f, "; {} of {} words", e.count, e.total)?;
            } else {
                write!(f, "; {} of {} words in -{}", e.count, e.total, e.ending)?;
            }
        }
        Ok(())
    }
}

/// A [`Choice`] written as data: its rules (`ending => [value count, …]`,
/// sorted by ending read backwards) and its listed words (`word => value`,
/// sorted).
///
/// ```
/// use flexion::{Choice, choice};
/// static GENDER: Choice<'static, u8> = choice! {
///     rules {
///         "" => [0 120, 1 80],
///         "а" => [1 75, 0 5],
///     }
///     listed {
///         "папа" => 0,
///     }
/// };
/// assert_eq!(GENDER.read("мама", 2.0, |_| true)[0].value, 1);
/// assert_eq!(GENDER.read("папа", 2.0, |_| true)[0].value, 0);
/// ```
#[macro_export]
macro_rules! choice {
    (
        rules { $( $ending:literal => [ $( $value:tt $count:literal ),* $(,)? ] ),* $(,)? }
        listed { $( $word:literal => $listed:tt ),* $(,)? }
    ) => {
        $crate::Choice {
            rules: ::std::borrow::Cow::Borrowed(&[ $(
                $crate::Rule {
                    ending: ::std::borrow::Cow::Borrowed($ending),
                    counts: ::std::borrow::Cow::Borrowed(&[ $( ($value, $count) ),* ]),
                }
            ),* ]),
            exceptions: ::std::borrow::Cow::Borrowed(&[ $(
                (::std::borrow::Cow::Borrowed($word), $listed)
            ),* ]),
        }
    };
}

/// Irregular forms written as data: `word CELL form`, one per line, sorted
/// by word and cell.
#[macro_export]
macro_rules! irregular {
    ( $( $word:literal $cell:ident $form:literal ),* $(,)? ) => {
        &[ $( (::std::borrow::Cow::Borrowed($word), $cell, ::std::borrow::Cow::Borrowed($form)) ),* ]
    };
}

/// A cell of a paradigm table: a pattern (`"~а"`), or `referred` for a
/// cell whose form is another cell's (see [`Referral`]).
#[macro_export]
macro_rules! form {
    (referred) => {
        $crate::Form::Referred
    };
    ($pattern:literal) => {
        $crate::Form::Pattern(::std::borrow::Cow::Borrowed($pattern))
    };
}
